```javascript
import * as THREE from 'three/webgpu';
import { texture, uv, vec3, float, mix } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-collection-row';

  const pos = config.scenePosition || { x: 0, y: 0.7, z: 0 };
  const rot = config.sceneRotation || { x: 0, y: 0, z: 0 };
  const scl = config.sceneScale || { x: 1, y: 1, z: 1 };
  group.position.set(pos.x, pos.y, pos.z);
  group.rotation.set(rot.x, rot.y, rot.z);
  group.scale.set(scl.x, scl.y, scl.z);

  const width = 6.4;
  const height = 0.72;

  const colors = {
    ink: new THREE.Color('#16161d'),
    paper: new THREE.Color('#e8ecf2'),
    accent: new THREE.Color('#ff2a38'),
    surface: new THREE.Color('#0b0b10'),
  };

  // Background plane (row surface)
  const bgGeo = new THREE.PlaneGeometry(width, height);
  const bgMat = new THREE.MeshBasicNodeMaterial({ transparent: true });

  const rowTex = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');
  rowTex.colorSpace = THREE.SRGBColorSpace;

  const uvNode = uv();
  const texNode = texture(rowTex, uvNode);
  const tint = vec3(colors.surface.r, colors.surface.g, colors.surface.b);
  bgMat.colorNode = mix(texNode.rgb, tint, float(0.6));
  bgMat.opacityNode = float(0.85);

  const bgMesh = new THREE.Mesh(bgGeo, bgMat);
  bgMesh.name = 'row-bg';
  group.add(bgMesh);

  // Divider line at bottom of row
  const dividerGeo = new THREE.PlaneGeometry(width * 0.94, 0.01);
  const dividerMat = new THREE.MeshBasicNodeMaterial({
    color: colors.paper,
    transparent: true,
    opacity: 0.25,
  });
  const divider = new THREE.Mesh(dividerGeo, dividerMat);
  divider.position.set(0, -height / 2 + 0.02, 0.001);
  divider.name = 'row-divider';
  group.add(divider);

  // Title text (Lora display font)
  const titleMesh = ctx.fontAtlas.createText({
    text: 'Item Title',
    font: 'display',
    weight: 400,
    size: 0.2,
    color: '#e8ecf2',
    align: 'left',
  });
  titleMesh.name = 'row-title';
  titleMesh.position.set(-width / 2 + 0.5, 0.08, 0.002);
  group.add(titleMesh);

  // Meta text (JetBrains Mono)
  const metaMesh = ctx.fontAtlas.createText({
    text: 'meta',
    font: 'text',
    weight: 400,
    size: 0.09,
    color: '#e8ecf2',
    opacity: 0.6,
    align: 'right',
  });
  metaMesh.name = 'row-meta';
  metaMesh.position.set(width / 2 - 0.5, -0.06, 0.002);
  group.add(metaMesh);

  // Accent edge (hidden by default, shown on focus)
  const accentGeo = new THREE.PlaneGeometry(0.04, height);
  const accentMat = new THREE.MeshBasicNodeMaterial({
    color: colors.accent,
    transparent: true,
    opacity: 0,
  });
  const accentEdge = new THREE.Mesh(accentGeo, accentMat);
  accentEdge.position.set(-width / 2 + 0.02, 0, 0.002);
  accentEdge.name = 'row-accent-edge';
  group.add(accentEdge);

  // Interaction state
  const baseY = pos.y;
  let hovered = false;
  let pressed = false;
  let currentTween = null;

  function riseIn() {
    if (currentTween) currentTween.kill();
    currentTween = gsap.to(group.position, {
      y: baseY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
    gsap.to(accentMat, { opacity: 0.9, duration: 0.3 });
  }

  function riseOut() {
    if (currentTween) currentTween.kill();
    currentTween = gsap.to(group.position, {
      y: baseY,
      duration: 0.7,
      ease: 'power3.out',
    });
    gsap.to(accentMat, { opacity: 0, duration: 0.3 });
  }

  function pressDown() {
    if (pressed) return;
    pressed = true;
    gsap.to(group.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out',
      onComplete: () => {
        gsap.to(group.scale, {
          x: scl.x,
          y: scl.y,
          z: scl.z,
          duration: 0.15,
          ease: 'power2.out',
        });
        pressed = false;
      },
    });
  }

  group.userData.handlers = {
    onPointerOver: () => {
      if (hovered) return;
      hovered = true;
      riseIn();
    },
    onPointerOut: () => {
      if (!hovered) return;
      hovered = false;
      riseOut();
    },
    onClick: () => {
      pressDown();
      if (ctx.emit) {
        ctx.emit('hub-collection.select', { nodeId: config.id || 'hub-collection-row' });
      }
    },
  };

  group.userData.cleanup = () => {
    if (currentTween) currentTween.kill();
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(accentMat);

    bgGeo.dispose();
    bgMat.dispose();
    dividerGeo.dispose();
    dividerMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
    rowTex.dispose();

    if (titleMesh.userData?.cleanup) titleMesh.userData.cleanup();
    if (metaMesh.userData?.cleanup) metaMesh.userData.cleanup();
  };

  return group;
}
